"""Generate docs/REPORT.md from the measured result files, so every number in the report comes from a run.

Inputs : ml/reports/intent_eval.json, speech_eval_*.json, multilingual_eval.json, ml/data/stats.json, train_config.json
Output : docs/REPORT.md          Run:  python ml/scripts/build_report.py
Prose (disclosures, limitations) is written here; figures are formatted from the JSON files.
"""
from __future__ import annotations

import glob
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(Path(__file__).resolve().parent))
from build_dataset import SEEDS  # noqa: E402

L = lambda p: json.loads(Path(p).read_text(encoding="utf-8")) if Path(p).exists() else None
pc = lambda x, d=1: f"{x * 100:.{d}f}%"
ci = lambda v: f"{pc(v[0])} – {pc(v[1])}"


def main() -> None:
    r = L(ROOT / "reports" / "intent_eval.json")
    cfg = L(ROOT / "artifacts" / "intent_model" / "train_config.json")
    ml = L(ROOT / "reports" / "multilingual_eval.json")
    sp_files = sorted(glob.glob(str(ROOT / "reports" / "speech_eval_*.json")))
    sp = L(sp_files[-1]) if sp_files else None
    a, b = r["A_baseline_tfidf_logreg"], r["A_distilbert"]
    bs, cal, pol = r["bootstrap_95ci"], r["calibration"], r["policy"]["params"]
    B, C = r["BC_test"]["B_argmax_no_clarification"], r["BC_test"]["C_error_aware"]
    Bc, Cc = r["BC_test"]["B_clear_only"], r["BC_test"]["C_clear_only"]
    Ba, Ca = r["BC_test"]["B_ambiguous_only"], r["BC_test"]["C_ambiguous_only"]
    SB, SC = r["E_stress"]["B_argmax_no_clarification"], r["E_stress"]["C_error_aware"]
    D = r["D_memory_ablation"]
    sz = r["sizes"]
    n_seeds = sum(len(v) for v in SEEDS.values())
    pcf = sorted(b["per_class"].items(), key=lambda kv: -kv[1]["f1"])
    weakest = pcf[-3:][::-1]
    out: list[str] = []
    w = out.append

    w("# VoxSure: an error-aware, multilingual voice assistant for student support\n")
    w("**Live application:** _not deployed yet: add the URL after deployment (see `docs/DEPLOYMENT.md`)_  ")
    w("**Source code:** _add repository link_  ")
    w("**Colab training notebook:** `ml/notebooks/VoxSure_Train_Colab.ipynb`\n")
    w("Every figure below is generated by `ml/scripts/build_report.py` from result files written by reproducible runs (`ml/reports/*.json`, seed 42). Nothing is typed in by hand.\n")

    w("## 1. Abstract\n")
    w(f"VoxSure is a browser voice assistant for a bounded Student Support & Campus Information domain. Speech is transcribed with Whisper "
      f"(`faster-whisper`), the transcript is shown with doubtful words underlined and can be edited, and a fine-tuned DistilBERT classifier "
      f"predicts one of {len(r['labels']) - 1} intents plus an explicit out-of-scope class. A recovery policy then decides to **answer** from a reviewed "
      f"knowledge base, **ask a targeted clarification**, or **fall back transparently**, instead of always guessing. On a held-out test set the policy "
      f"reduced the rate of confidently wrong answers from {pc(B['wrong_answer_rate'])} (always answer) to {pc(C['wrong_answer_rate'])}, at the cost of asking "
      f"for clarification on {pc(C['clarification_rate'])} of turns. The system replies in the user's language (Hindi, Punjabi and German were measured; "
      f"others are best effort) and, if an AI provider is configured, can answer non-campus questions with clearly labelled AI-generated replies. "
      f"The dataset is small and author-written, so absolute numbers are optimistic relative to real users; see Limitations.\n")

    w("## 2. Problem and related work\n")
    w("Misrecognised words and ambiguous requests cause voice assistants to give confident but irrelevant answers. Relevant prior work: Whisper for robust "
      "ASR (Radford et al., 2022); DistilBERT, a compact distilled transformer (Sanh et al., 2019); out-of-scope intent detection datasets such as CLINC150 "
      "(Larson et al., 2019); over-confidence of modern networks and temperature scaling (Guo et al., 2017); and NLLB-200 for translation across 200 "
      "languages (NLLB Team, 2022). Uncertainty-aware intent clarification already exists in the literature, so the contribution claimed here is narrower: "
      "a **reproducible, measured evaluation of a recovery workflow** (transcript editing, uncertainty and ambiguity handling, targeted clarification, optional "
      "consent-based correction memory) in one defined domain, compared against a no-clarification baseline, plus an honest multilingual extension.\n")

    w("## 3. Dataset\n")
    w(f"* **Source:** all {n_seeds} seed utterances were written by the author for this project (no scraped or third-party data). Seeds were expanded "
      "programmatically with conversational fillers, ASR-style normalisation and plausible ASR substitutions (e.g. \"hostel\"→\"hostile\"). Script: `ml/scripts/build_dataset.py`.")
    w(f"* **Classes ({len(r['labels'])}):** " + ", ".join(r["labels"]) + ".")
    w(f"* **Splits** (by seed group within each class, so variants of one seed never straddle splits; zero exact-text overlap): train {sz['train']}, validation {sz['val']}, test {sz['test']}. Fixed seed 42.")
    w(f"* **Ambiguous set (evaluation only, never trained on):** {sz['ambiguous_val'] + sz['ambiguous_test']} hand-written under-specified requests; {sz['ambiguous_val']} for policy tuning, {sz['ambiguous_test']} held out for test.")
    w("* **Dataset history (disclosed):** version 1 had 13 classes. (2) `about_bot` and `help_capabilities` were added after manual testing showed \"What's your name?\" fell into the out-of-scope fallback. "
      "(3) A run showed `thanks_bye` with F1 = 0.00 on test (only 12 seeds), so more small-talk seeds were added. (4) More varied seeds were added for weak classes (campus services, hostel, IT, scholarship, fees, exams) "
      "and the test set enlarged. Each change regenerated the splits and all results; metrics from earlier versions are superseded and not reported. This is a mild form of test-set feedback.")
    w("* **Knowledge base:** answers use illustrative values for a fictional campus (not real institutional data). Each answer carries a source label and a real last-updated date; no links are shown because none exist for an illustrative campus.\n")

    w("## 4. Models and method\n")
    w("| Component | Choice |\n|---|---|")
    w(f"| ASR | `faster-whisper` `small` (multilingual, int8, CPU), VAD filter, per-word probabilities; auto language detection or user-selected language |")
    w(f"| Intent classifier | `{cfg['base_model']}` fine-tuned, {len(r['labels'])} classes, max length {cfg['max_len']}, AdamW lr {cfg['lr']}, batch {cfg['batch_size']}, {cfg['epochs']} epochs, seed {cfg['seed']}, best epoch by validation accuracy ({pc(cfg['best_val_acc'])}) |")
    w(f"| Confidence | Softmax with temperature scaling, T = {cfg['temperature']:.2f} fitted on validation data only |")
    w("| Baseline | TF-IDF (1-2 grams) + Logistic Regression (experimental baseline only) |")
    w(f"| Policy | answer threshold {pol['t_high']:.2f}, margin {pol['margin']:.2f}, low-confidence threshold {pol['t_low']:.2f}, out-of-scope threshold {pol['t_oos']:.2f}; grid-searched on **validation + ambiguous_val only**, then frozen before test evaluation |")
    w("| Translation | NLLB-200 distilled 600M (int8, CTranslate2): non-English input → English → classifier. Hindi, Punjabi and German replies are hand-written; other languages use NLLB with a numeric-consistency guard |")
    w("| Open-domain answers | Optional external AI provider (Claude or any OpenAI-compatible service) for questions the classifier marks out-of-scope; labelled AI-generated; user opt-out; daily cap |\n")
    w("Policy objective on validation: reward correct answers/fallbacks and appropriate clarifications (0.6), penalise a wrong answer 3× and an unnecessary clarification 0.6×. "
      "A \"wrong answer\" is (a) answering with the wrong intent, (b) answering an out-of-scope request (with the AI provider off), or (c) answering an ambiguous request at all.\n")

    w("## 5. Results\n")
    w(f"### 5.1 Experiment A: text-only intent classification (test, n = {sz['test']})\n")
    w("| Model | Accuracy | Macro-F1 (95% bootstrap CI) |\n|---|---|---|")
    w(f"| TF-IDF + LogReg baseline | {a['accuracy']:.3f} | {a['macro_f1']:.3f} ({bs['macro_f1_baseline'][0]:.3f} – {bs['macro_f1_baseline'][1]:.3f}) |")
    w(f"| Fine-tuned DistilBERT | {b['accuracy']:.3f} | **{b['macro_f1']:.3f}** ({bs['macro_f1_distilbert'][0]:.3f} – {bs['macro_f1_distilbert'][1]:.3f}) |\n")
    w("The two intervals do not overlap, so the gap over the baseline is not a resampling artefact. Per-class test F1 (DistilBERT): " +
      ", ".join(f"{k} {v['f1']:.2f}" for k, v in pcf) + ". Confusion matrix: `ml/reports/confusion_matrix.png` and the dashboard.\n")
    w("Weakest classes: " + "; ".join(f"**{k}** ({v['f1']:.2f}, {v['support']} test items)" for k, v in weakest) +
      ". Each class has few distinct held-out phrasings, so single-class scores are high-variance, and earlier dataset versions of the same pipeline scored noticeably differently, "
      "so **differences of several points should be treated as noise**.\n")
    w(f"**Calibration.** ECE on test: {cal['ece_test_uncalibrated']:.3f} uncalibrated vs {cal['ece_test_calibrated']:.3f} after temperature scaling; mean test confidence {pc(cal['mean_conf_test_calibrated'])} vs accuracy {pc(cal['acc_test'])}. "
      "Confidence drives decisions, so thresholds are tuned empirically rather than trusting raw probabilities.\n")

    w(f"### 5.2 Experiments B vs C: no recovery vs error-aware recovery (test n = {C['n']} = {Bc['n']} clear + {Ba['n']} ambiguous)\n")
    w("| Metric | B: always answer | C: error-aware |\n|---|---|---|")
    w(f"| Wrong-answer rate, all turns (95% CI) | {pc(B['wrong_answer_rate'])} ({ci(bs['wrong_answer_rate_B'])}) | **{pc(C['wrong_answer_rate'])}** ({ci(bs['wrong_answer_rate_C'])}) |")
    w(f"| Clarification rate | {pc(B['clarification_rate'])} | {pc(C['clarification_rate'])} ({ci(bs['clarification_rate_C'])}) |")
    w(f"| Wrong-answer rate, clear requests only | {pc(Bc['wrong_answer_rate'])} | {pc(Cc['wrong_answer_rate'])} |")
    w(f"| Task completion in one turn (clear requests) | {pc(Bc['task_completion_one_turn'])} | {pc(Cc['task_completion_one_turn'])} |")
    w(f"| Task completion if the user taps a clarification option | {pc(Bc['task_completion_with_option_click'])} | {pc(Cc['task_completion_with_option_click'])} |")
    w(f"| Ambiguous requests answered (wrongly) | {Ba['wrong_answer']}/{Ba['n']} | {Ca['wrong_answer']}/{Ca['n']} ({Ca['appropriate_clarify']} clarified) |\n")
    w(f"The reduction in wrong-answer rate is {ci(bs['wrong_answer_rate_reduction_B_minus_C'])} (95% CI). Trade-off: the policy asks an unnecessary clarification on {Cc['unnecessary_clarify']} of {Cc['n']} clear requests "
      f"({pc(Cc['unnecessary_clarify'] / Cc['n'], 0)}), and even counting a tap on an offered option it completes {'fewer' if Cc['task_completion_with_option_click'] < Bc['task_completion_with_option_click'] else 'more'} tasks than the baseline "
      f"({pc(Cc['task_completion_with_option_click'])} vs {pc(Bc['task_completion_with_option_click'])}). Whether this trade is right depends on the cost of a wrong answer versus an extra question; thresholds should be re-tuned with real users.\n")

    w("### 5.3 Experiment E: noise stress (test text with heavier synthetic corruption)\n")
    w(f"Text-only accuracy on stressed clear requests: {pc(r['E_stress']['text_only_accuracy_on_stressed_clear'])}. Wrong-answer rate: B {pc(SB['wrong_answer_rate'])} vs C {pc(SC['wrong_answer_rate'])}; "
      f"clarification rate C {pc(SC['clarification_rate'])}; one-turn completion B {pc(SB['task_completion_one_turn'])} vs C {pc(SC['task_completion_one_turn'])} ({pc(SC['task_completion_with_option_click'])} with an option tap). "
      "Under heavy corruption the policy is very conservative.\n")

    w("### 5.4 Speech pipeline\n")
    if sp:
        w(f"Whisper `{sp['asr_model']}` on {sp['n_utterances']} synthetic test utterances (2 Windows text-to-speech voices); white noise added at the stated SNR.\n")
        w("| Condition | WER (domain prompt) | Latency p50 / p95 (s) | Wrong answers: always answer → VoxSure |\n|---|---|---|---|")
        for c_, v in sp["conditions"].items():
            wp = v["with_domain_prompt"]
            w(f"| {'Clean' if c_ == 'clean' else c_.replace('snr', 'SNR ') + ' dB'} | {pc(wp['wer'])} | {wp['latency_s_median']:.2f} / {wp['latency_s_p95']:.2f} | "
              f"{pc(wp['pipeline_B_argmax']['wrong_answer_rate'])} → {pc(wp['pipeline_C_error_aware']['wrong_answer_rate'])} |")
        cl = sp["conditions"]["clean"]
        if "no_prompt" in cl:
            w(f"\nOn clean audio, WER without the domain prompt was {pc(cl['no_prompt']['wer'])} versus {pc(cl['with_domain_prompt']['wer'])} with it. ")
        if "auto_detect" in cl:
            ad = cl["auto_detect"]
            w(f"With automatic language detection (what the app does by default) on English audio, WER was {pc(ad['wer'])} and the language was detected as English in {pc(ad['detected_english_rate'])} of clips.")
        w("\n**Caveats:** the audio is clean synthetic speech from two voices, so these figures say nothing about accents, spontaneous speech or real microphones: WER here is a lower bound. "
          "Latency was measured on the author's laptop CPU (int8, no GPU) while other jobs were also using the CPU, so it is pessimistic; an idle machine should be faster. Human recordings were not collected.\n")
    else:
        w("_Speech evaluation results are not available in this build._\n")

    w("### 5.5 Experiment D: correction memory (simulation)\n")
    w(f"Of {D['n_stressed_utterances']} stressed utterances, {D['pass1_not_answered_correctly']} were not answered correctly on first pass and the corrected text was \"remembered\". "
      f"When the same utterances recurred, the correct-answer rate was {pc(D['pass2_correct_answer_rate_memory_off'])} without memory vs {pc(D['pass2_correct_answer_rate_memory_on'])} with it. "
      "This is an **upper bound for exact repeats**: memory matches only the identical normalised utterance and does not generalise. No real-user study was done.\n")

    w("### 5.6 Multilingual (typed text → translation → classifier → reply)\n")
    if ml:
        langs = ml["languages"]
        w(f"{ml['n_per_language']} sentences per language covering every intent plus out-of-scope, **written by the author and not verified by native speakers**; never used for training or tuning. "
          "English is the control. A language is labelled *verified* only if it met criteria fixed in advance: intent accuracy ≥ 80%, wrong-answer rate with recovery ≤ 10%, language-ID accuracy ≥ 95%.\n")
        w("| Language | Intent accuracy | Macro-F1 | Language ID | Wrong answers: always answer → VoxSure | Clarification | Translation p50 (s) | Label |\n|---|---|---|---|---|---|---|---|")
        for k, v in langs.items():
            w(f"| {v['name']} | {pc(v['accuracy'])} | {v['macro_f1']:.3f} | {pc(v['lang_id_accuracy'])} | {pc(v['wrong_answer_rate_B'])} → {pc(v['wrong_answer_rate_C'])} | "
              f"{pc(v['clarification_rate_C'])} | {v['translate_latency_s_median']:.2f} | {'verified' if v['verified'] else 'best effort'} |")
        mt = ml.get("machine_translation_number_check", {})
        if mt:
            w("\n**Reply side.** Raw machine translation changed a number in some fixed answers: " +
              "; ".join(f"{k}: {v['numbers_changed_by_machine_translation']}/{v['answers_with_numbers']}" for k, v in mt.items()) +
              " (answers containing numbers). A Hindi example in testing turned a 9 am opening time into \"night nine\". For this reason Hindi, Punjabi and German replies are **hand-written** "
              "(also unverified by native speakers), and other languages use machine translation with a numeric-consistency guard that warns the user when a number changed. "
              "The guard only checks digits, so other translation errors are possible; an English original is always shown.\n")
        w("**Not measured:** speech recognition accuracy (WER) for Hindi, Punjabi and German, which needs human recordings; languages other than these four; romanised or mixed-language text.\n")
    else:
        w("_Multilingual results are not available in this build._\n")

    w("### 5.7 Open-domain answers\n")
    w("Non-campus questions can be answered by an external AI provider (Claude or any OpenAI-compatible service). **No accuracy metric is reported for these answers**: they are not from the reviewed knowledge base, "
      "can be wrong, and are labelled as such. The integration (routing, opt-out, history, provider selection, failure fallback, daily cap, key loading) is covered by automated tests using stand-in providers and a local mock "
      "server; a call to a real provider has not been exercised in this repository because no key was available.\n")

    w("## 6. System and deployment\n")
    w("React + TypeScript + Tailwind frontend (live microphone waveform, per-word transcript highlighting, language badges, source labels, Pipeline insights panel, evaluation dashboard at `#/evaluation`); "
      "FastAPI backend with rate limiting and security headers; SQLite (default) or PostgreSQL for opt-in correction memory and metrics-only events; one Docker image serving both on a single HTTPS origin "
      "(`docs/ARCHITECTURE.md`, `docs/DEPLOYMENT.md`). Audio is never persisted and logged events contain no transcript text. The Docker image has **not been built** (Docker is unavailable on the development machine) and the app is **not deployed**.\n")
    w("Automated tests: backend (policy, every endpoint, multilingual flow, curated translations and numeric guard, general-answer routing and providers, failure paths, privacy, rate limiting) and frontend "
      "(components, evaluation page, axe accessibility audits). Counts are in the README.\n")

    w("## 7. Limitations and future work\n")
    for t in [
        "Author-written, templated dataset; test sentences come from the same author and distribution, so real-user accuracy is expected to be lower.",
        "Small test set with few distinct phrasings per class; results varied noticeably across dataset versions; intervals reflect resampling of this test set only.",
        f"The weakest classes ({', '.join(k for k, _ in weakest)}) need more diverse real utterances.",
        f"{pc(Cc['unnecessary_clarify'] / Cc['n'], 0)} unnecessary clarifications on clear requests and lower one-turn completion than the baseline are a real usability cost; some ambiguous prompts are still answered confidently.",
        "ASR evaluated on synthetic English speech only. Needs human recordings across accents and noise, and any speech evaluation for Hindi, Punjabi and German.",
        "Multilingual test sentences and hand-written replies are not native-speaker verified; translation relies on English-trained models; other languages are best effort.",
        "AI-generated general answers are unmeasured and can be wrong; they involve sending text to an external provider (disclosed in the UI).",
        "Knowledge-base content is illustrative; browser speech synthesis availability varies, especially for non-English voices; correction memory is exact-match only.",
        "The dataset was revised several times after observing weak results (§3).",
        "Public deployment, the Docker build and real-microphone/real-provider checks remain to be done by the owner.",
    ]:
        w(f"* {t}")
    w("\n## References\n")
    for t in ["Radford, A. et al. (2022). Robust Speech Recognition via Large-Scale Weak Supervision (Whisper).",
              "Sanh, V. et al. (2019). DistilBERT, a distilled version of BERT.",
              "Guo, C. et al. (2017). On Calibration of Modern Neural Networks. ICML.",
              "Larson, S. et al. (2019). An Evaluation Dataset for Intent Classification and Out-of-Scope Prediction (CLINC150). EMNLP.",
              "NLLB Team (2022). No Language Left Behind: Scaling Human-Centered Machine Translation.",
              "SYSTRAN. faster-whisper (CTranslate2 implementation of Whisper)."]:
        w(f"* {t}")
    (ROOT.parent / "docs" / "REPORT.md").write_text("\n".join(out) + "\n", encoding="utf-8")
    print("wrote docs/REPORT.md", f"({len(out)} lines)")


if __name__ == "__main__":
    main()
